<div class="page-heading"><div><span class="eyebrow">Admin · Date-wise report</span><h1>Child vaccination report</h1><p>Filter completed vaccinations by the date on which each dose was administered.</p></div><button class="button button-secondary" type="button" data-print>Print report</button></div>
<form class="filter-bar report-filter" method="get" action="index.php"><input type="hidden" name="route" value="admin.reports"><label>From<input type="date" name="from" value="<?= e($from) ?>" required></label><label>To<input type="date" name="to" value="<?= e($to) ?>" required></label><button class="button button-small" type="submit">Apply dates</button></form>
<section class="panel table-panel"><div class="panel-heading"><div><span class="eyebrow"><?= count($records) ?> result<?= count($records) === 1 ? '' : 's' ?></span><h2><?= e(display_date($from)) ?> to <?= e(display_date($to)) ?></h2></div></div>
<?php if (!$records): ?><div class="empty-inline"><p>No vaccinations were recorded in this date range.</p></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Vaccination date</th><th>Child</th><th>Parent</th><th>Vaccine</th><th>Hospital</th><th>Batch</th></tr></thead><tbody><?php foreach ($records as $record): ?><tr><td><strong><?= e(display_date($record['administered_at'])) ?></strong><small><?= e(display_date($record['administered_at'], 'g:i A')) ?></small></td><td><?= e($record['child_name']) ?><small>Born <?= e(display_date($record['date_of_birth'])) ?></small></td><td><?= e($record['parent_name']) ?></td><td><?= e($record['vaccine_name']) ?><small><?= e($record['dose_label']) ?></small></td><td><?= e($record['hospital_name']) ?></td><td><?= e($record['batch_number'] ?: 'Not recorded') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
